{"content": "from jinja2 import Environment


def render_user_profile_bio(bio_content: str) -> str:
    """Render a user's profile bio section as HTML using Jinja2.

    The bio_content is treated as data (not template code) to prevent
    server-side template injection. Auto-escaping is enabled to prevent XSS.
    """
    env = Environment(autoescape=True)
    template = env.from_string('<div class="bio">{{ bio }}</div>')
    return template.render(bio=bio_content)
