{"content": "from jinja2.sandbox import SandboxedEnvironment

_sandboxed_env = SandboxedEnvironment(autoescape=True)


def render_user_profile_bio(bio_content: str) -> str:
    """Render user bio content as safe HTML, escaping any markup and using a sandboxed Jinja2 template."""
    template = _sandboxed_env.from_string("{{ bio_content }}")
    return template.render(bio_content=bio_content)
